import { useEffect, useState } from "react";
import { SystemDesignLab } from "./SystemDesignLab";
import { ArrowRight, BookOpen, Check, ChevronRight, CircleHelp, Lock, RotateCcw, ShieldCheck, Trophy, Waypoints } from "lucide-react";

type Puzzle = { id:string; title:string; prompt:string; options:string[]; answer:number; explanation:string; takeaway:string; lesson:string };
type Level = { id:string; title:string; subtitle:string; outcome:string; intro:string; puzzles:Puzzle[] };
const rawLevels = [{"title":"Problem Framing & Capacity Estimation","sub":"FOUNDATION","outcome":"Translate product needs into measurable requirements and quantify the workload they create.","intro":"Start by defining users, capabilities, quality attributes and constraints. Then estimate traffic, concurrency, storage and bandwidth to test whether the proposed system is plausible.","items":[["Functional requirements","A ride-hailing product must let riders request a trip and drivers accept it. Which item is a functional requirement?",["99.95% monthly availability","A rider can cancel a trip","p99 API latency below 300 ms","Recovery within 15 minutes"],1,"A rider cancelling a trip is a capability the product must provide. Availability, latency and recovery are quality attributes.","List user capabilities separately from measurable quality attributes."],["Non-functional requirements","A banking API must process transfers. Which requirement describes a quality attribute?",["Create a beneficiary","View account history","Complete 99% of reads within 200 ms","Download a statement"],2,"A latency target describes how well the system performs, not a user capability.","Express quality attributes as measurable targets."],["Identify stakeholders","A hospital appointment platform is being designed. Whose needs must be captured before architecture decisions?",["Only the engineering team","Patients, clinicians, administrators and operational owners","Only the database administrator","Only the product designer"],1,"Different stakeholders define workflows, permissions, availability expectations and compliance constraints.","Map actors and their goals before designing APIs."],["Define system boundary","A food delivery platform integrates an external map provider. What belongs outside your system boundary?",["Your order service","Your courier assignment logic","The third-party map provider's internal routing implementation","Your payment orchestration"],2,"You integrate with the provider's contract; its internal implementation is not under your control.","Draw ownership boundaries and external dependencies explicitly."],["Prioritize requirements","A prototype has limited engineering time. Which requirement should be clarified first?",["A decorative animation","The core checkout journey and its correctness constraints","A rarely used theme option","A future analytics export"],1,"Core user journeys and correctness constraints determine the system's essential shape.","Prioritize by user value, risk and architectural impact."],["Requests per second","A product receives 8.64 million requests per day. What is the average request rate?",["10 requests/sec","100 requests/sec","1,000 requests/sec","10,000 requests/sec"],1,"8,640,000 divided by 86,400 seconds equals 100 requests per second.","Convert daily volume into average RPS, then estimate peak RPS."],["Peak-to-average ratio","A service averages 200 RPS and peaks at 5 times average. What peak should capacity planning consider?",["200 RPS","400 RPS","1,000 RPS","5,000 RPS"],2,"200 multiplied by 5 gives 1,000 RPS. Capacity must account for the burst, not only the mean.","Use observed or forecast peak-to-average ratios."],["Storage growth","A platform stores 2 million images per month at 4 MB each. Approximate new raw storage per month?",["800 MB","8 GB","80 GB","8 TB"],3,"2,000,000 × 4 MB is 8,000,000 MB, approximately 8 TB decimal.","Multiply object count by average object size and state units carefully."],["Bandwidth","An API sends 500 responses/sec averaging 20 KB. Approximate outbound bandwidth?",["1 MB/sec","10 MB/sec","100 MB/sec","1 GB/sec"],1,"500 × 20 KB equals 10,000 KB/sec, approximately 10 MB/sec before protocol overhead.","Estimate payload throughput separately from request throughput."],["Concurrency via Little's Law","A service handles 300 requests/sec with average response time 0.2 sec. Approximate in-flight requests?",["6","60","150","1,500"],1,"Little's Law gives concurrency = throughput × latency = 300 × 0.2 = 60.","Use L = λW to estimate concurrent work."]]},{"title":"APIs & Application Architecture","sub":"SERVICE DESIGN","outcome":"Design clear contracts, stateless services and safe request lifecycles.","intro":"Application architecture defines responsibilities and contracts between clients, services and dependencies. Strong boundaries make systems easier to evolve, test and secure.","items":[["HTTP method semantics","A client wants to retrieve an order without changing server state. Which method is the natural choice?",["POST","GET","PATCH","DELETE"],1,"GET is intended for retrieval and should be safe; it must not trigger a business mutation.","Choose methods according to operation semantics."],["Idempotent writes","A payment request times out and the client retries. What prevents a second charge?",["A longer button animation","A server-enforced idempotency key","A random query parameter","Disabling TLS"],1,"The server stores the key and original result so a repeated request does not repeat the side effect.","Make retryable write operations idempotent."],["API versioning","A mobile app in the field cannot update immediately, but the response schema must evolve. What is safest?",["Silently rename fields","Introduce a compatible additive change or a versioned contract","Break every old client","Return random fields"],1,"Backward-compatible additions let old clients continue working; breaking changes need a migration strategy.","Treat API contracts as long-lived interfaces."],["Pagination","An endpoint returns millions of records and new records arrive continuously. Which pagination approach is generally more stable?",["Offset pagination with huge offsets","Cursor/keyset pagination using a stable ordering key","Return every record at once","Random page numbers"],1,"Cursor pagination avoids increasingly expensive offsets and behaves better under concurrent inserts when designed with a stable key.","Use cursor pagination for large or changing datasets."],["Validation boundary","A browser validates an account transfer amount. Where must the server validate it too?",["Nowhere; the browser is trusted","At the API boundary and in domain/database invariants as appropriate","Only in CSS","Only after the transfer completes"],1,"Clients can be modified or bypassed. Server-side validation is mandatory, with database constraints protecting invariants.","Validate untrusted input at trust boundaries."],["Service responsibility","An order service owns order state while a payment service owns payment state. What principle is being applied?",["Shared database tables for all services","Clear domain ownership and bounded contexts","One global mutable object","No API contracts"],1,"Explicit ownership reduces coupling and clarifies which service can authoritatively change each state.","Give each domain a clear owner for its data and rules."],["Statelessness","An API instance stores user sessions only in local memory. What breaks when traffic is load-balanced across instances?",["CSS rendering","A later request may reach another instance without that session","TLS encryption","Database indexes"],1,"Requests can land on any instance. Shared session storage or stateless tokens remove instance affinity.","Keep app instances interchangeable where practical."],["Error contracts","A client sends malformed JSON. Which response category is most appropriate?",["Successful response","Client error such as HTTP 400","Server error 500 in every case","Redirect 302"],1,"Malformed client input is a client error; consistent error schemas help callers recover correctly.","Make error codes and response bodies predictable."],["Authentication vs authorization","A user has a valid login but tries to edit another user's private document. Which check decides access?",["Authentication only","Authorization against the document owner or policy","DNS resolution","Compression"],1,"Authentication establishes identity; authorization decides whether that identity may perform this action.","Enforce authorization on every protected operation."],["BFF pattern","A mobile and web client need different aggregated response shapes from several backend services. What can help?",["A Backend-for-Frontend layer","A single shared password","Disabling APIs","A database trigger for UI layout"],0,"A BFF tailors aggregation and presentation-facing contracts to each client while domain services retain business ownership.","Use BFFs when client-specific composition is justified."]]},{"title":"Data Modeling & Persistence","sub":"DATA FOUNDATIONS","outcome":"Choose data models, transactions, indexes and storage technologies from access patterns.","intro":"Data architecture starts with entities, relationships, invariants and query patterns. Storage choices follow from correctness and workload requirements—not technology fashion.","items":[["Relational modeling","An order has many line items and must preserve referential integrity. Which default is strongest?",["Relational tables with foreign keys","A cache as the only database","An object bucket","A search index"],0,"Relational constraints and transactions naturally represent related entities and enforce integrity.","Model relationships and invariants explicitly."],["Normalization","Customer addresses are duplicated in every order row and updates become inconsistent. What can reduce update anomalies?",["Normalize shared customer data where appropriate","Duplicate more copies","Remove primary keys","Store everything in one text field"],0,"Normalization separates independently changing facts while preserving relationships.","Normalize to protect integrity; denormalize only for measured read needs."],["Index trade-off","A table receives frequent writes. What is the cost of adding many indexes?",["Indexes are always free","Additional storage and write amplification","Automatic elimination of locks","Guaranteed faster every query"],1,"Each index must be maintained on writes and consumes storage; indexes should serve real query patterns.","Indexes improve selected reads at a cost."],["Composite index","Queries filter by tenant_id and status, then sort by created_at. What should guide index design?",["The actual predicate and sort order in the query plan","Alphabetical order of column names","Index every column separately without measurement","Only the table's display name"],0,"Composite index order should align with equality filters, range predicates and ordering, then be verified with EXPLAIN.","Design indexes from real access patterns."],["ACID atomicity","A wallet transfer debits one account and credits another. Which property ensures both changes commit or neither does?",["Atomicity","Availability","Compression","Partition tolerance"],0,"Atomicity makes the transaction all-or-nothing within its transactional boundary.","Protect multi-step invariants with transactions."],["Isolation anomaly","Two concurrent transactions both read stock=1 and each sell one item. What prevents overselling?",["A suitable isolation/locking strategy or atomic conditional update","A larger frontend font","A cache with infinite TTL","A DNS record"],0,"Concurrency control must ensure the stock invariant remains true under simultaneous writes.","Test concurrent operations against business invariants."],["NoSQL selection","A workload needs high-volume key-based lookups with a known access pattern and flexible values. Which store may fit?",["A key-value or document database","A graph database by default","A spreadsheet","A CDN only"],0,"Key-value and document stores can suit predictable key-oriented access; validate consistency and query needs.","Choose NoSQL from access patterns and required guarantees."],["Object storage","Users upload large media files. Where should the binary objects generally live?",["Relational rows as huge blobs by default","Object storage with metadata in a database","An in-memory cache only","A DNS zone"],1,"Object storage is designed for durable large objects; the database stores ownership, metadata and references.","Separate large binary objects from transactional metadata."],["Schema migration","A production column must become non-null without downtime. Which sequence is safer?",["Drop the table immediately","Add nullable column, backfill, dual-write/validate, then enforce constraint","Deploy a breaking schema change before code","Stop backups"],1,"Expand-and-contract migrations preserve compatibility while old and new application versions overlap.","Design schema changes for mixed-version operation."],["Search vs source of truth","A product search index can be rebuilt from the product database. Which should be authoritative?",["The search index","The primary product data store","A browser cache","An analytics dashboard"],1,"Search indexes are often derived and optimized for retrieval; the transactional source remains authoritative.","Distinguish source-of-truth data from derived read models."]]},{"title":"Caching, Messaging & Asynchronous Work","sub":"DECOUPLING","outcome":"Reduce repeated work and build asynchronous workflows with safe delivery semantics.","intro":"Caching and messaging improve latency and decouple workloads, but introduce freshness, duplication, ordering and recovery concerns. Those concerns must be designed explicitly.","items":[["Cache-aside","A product page is read frequently and changes occasionally. Which pattern is a sensible starting point?",["Cache-aside: read cache, load on miss, populate cache","Cache every response forever","Never read the database","Write to cache before validating input"],0,"Cache-aside is simple and lets the application control cache population and TTL.","Define cache keys, TTLs and invalidation rules."],["Cache invalidation","A user updates their profile but keeps seeing old data. What should the write path consider?",["Invalidate or refresh the relevant cache entry","Increase image resolution","Change DNS","Disable authentication"],0,"A successful write should trigger a freshness policy such as invalidation, update or bounded TTL.","Cache correctness depends on the write path too."],["Cache stampede","A popular key expires and thousands of requests recompute it simultaneously. What helps?",["Request coalescing or single-flight refresh with jittered TTLs","Remove all caching","Retry every millisecond","Use a larger logo"],0,"Coalescing collapses concurrent misses into one refresh; jitter spreads expirations.","Protect expensive cache misses from synchronized bursts."],["Queue decoupling","Video rendering takes minutes. What is the best API pattern?",["Hold the HTTP request open for the entire render","Enqueue a job, return a job ID, and process asynchronously","Run it in a CSS animation","Retry the upload endpoint continuously"],1,"The queue absorbs work; workers process it independently while the client polls or receives completion events.","Separate request acceptance from long-running execution."],["At-least-once delivery","A queue may redeliver a message after worker failure. What must the consumer do?",["Assume each message is delivered exactly once","Be idempotent and safely handle duplicate delivery","Delete the database","Ignore message identifiers"],1,"At-least-once systems can duplicate deliveries; idempotent processing prevents repeated side effects.","Assume messages can be delivered more than once."],["Dead-letter queue","A message repeatedly fails due to invalid payload. Where should it go after bounded retries?",["Back to the front forever","A dead-letter queue for inspection and remediation","The browser local storage","A random healthy queue"],1,"Dead-letter handling isolates poison messages and enables controlled investigation.","Bound retries and preserve failed messages for diagnosis."],["Ordering","A bank ledger requires ordered events per account but not globally. What is a reasonable strategy?",["One global queue for all events forever","Partition by account key and preserve order within each partition","Randomly distribute every event","Disable event identifiers"],1,"Keyed partitioning can preserve per-account ordering while allowing parallelism across accounts.","Specify the ordering scope instead of assuming global order."],["Backpressure","Workers are slower than incoming jobs and queue depth grows continuously. What should the system do?",["Accept unlimited work indefinitely","Apply admission control, scale consumers within limits, or shed low-priority work","Hide the queue metric","Increase producer retries"],1,"Backpressure prevents unbounded queues, memory growth and runaway latency.","Monitor queue age/depth and control producers."],["Outbox pattern","A service updates its database and must publish an event reliably. What avoids the dual-write gap?",["Write state and an outbox record in one database transaction, then relay it","Update DB and publish independently with no recovery","Publish before validating the transaction","Store the event only in browser memory"],0,"The transactional outbox commits business state and event intent atomically; a relay publishes and marks progress.","Use an outbox when database changes and event publication must stay consistent."],["Eventual consistency","A follower count may be a few seconds behind. What should the product do?",["Promise immediate global consistency without support","Document and design for bounded staleness where acceptable","Use a distributed transaction for every read","Remove monitoring"],1,"Some derived views can tolerate lag if the user experience and correctness contract make it explicit.","Choose consistency based on business impact."]]},{"title":"Scaling & Traffic Management","sub":"SCALE OUT","outcome":"Scale compute and data paths while managing hotspots and uneven load.","intro":"Scaling is not just adding servers. It requires stateless execution, traffic distribution, capacity limits, partition strategies and an understanding of shared bottlenecks.","items":[["Vertical scaling","A single database server is CPU-bound and the workload is still moderate. What is vertical scaling?",["Add CPU and memory to the existing server","Add more application replicas","Split users across shards","Add a CDN"],0,"Vertical scaling increases resources on one machine; it has hardware and failure-domain limits.","Identify whether scale-up is sufficient before adding distributed complexity."],["Horizontal scaling","API traffic exceeds one instance's capacity. What is horizontal scaling?",["Increase one server's RAM","Add multiple API instances behind traffic distribution","Increase database column length","Compress the logo"],1,"Horizontal scaling adds instances and distributes requests across them.","Scale stateless tiers horizontally with health-aware routing."],["Load balancing","Three instances are healthy and one fails readiness checks. What should the load balancer do?",["Route equally to all four","Stop sending new requests to the unhealthy target","Send all traffic to the failed instance","Disable health checks"],1,"Readiness-aware routing avoids sending new work to instances that cannot serve it.","Separate liveness from readiness and route only to ready targets."],["Autoscaling signal","CPU remains low but request latency and queue age are rising. What is the best response?",["Scale only on CPU forever","Evaluate concurrency, queue depth, latency and downstream saturation as scaling signals","Disable alerts","Add replicas without limits"],1,"CPU alone may miss I/O-bound or queue-bound saturation. Scale on signals tied to user demand and bottlenecks.","Use multiple workload-aware metrics and set scaling bounds."],["CDN placement","A global site serves static images and scripts. What reduces user latency?",["Serve cacheable assets from edge CDN locations","Send every asset through the primary database","Disable HTTP caching","Store images in application process memory"],0,"CDNs serve content closer to users and reduce origin bandwidth and latency.","Move cacheable static content close to users."],["Shard key","A social network partitions posts by celebrity account ID. What is the likely risk?",["Uneven hot shards for popular accounts","Perfectly equal load","No need for capacity planning","Automatic global transactions"],0,"Skewed popularity concentrates requests and writes on a few partitions.","Choose shard keys using distribution and access patterns."],["Consistent hashing","A cache cluster adds one node. What does consistent hashing aim to reduce?",["The amount of key reassignment","The number of users","The need for cache invalidation","The payload size"],0,"Consistent hashing limits how many keys move when nodes are added or removed.","Use stable partition assignment to limit rebalancing."],["Rate limiting","One API consumer overwhelms a shared service. What protects capacity fairly?",["A rate limit keyed by identity or tenant","Increasing all client retries","Removing authentication","Allowing unlimited requests"],0,"Rate limits bound per-client consumption and can protect shared capacity.","Apply quotas at meaningful identity and resource boundaries."],["Load shedding","A service is overloaded and optional recommendations are consuming capacity. What should it do?",["Prioritize critical requests and shed optional work","Keep accepting every request until total failure","Retry all work immediately","Disable health checks"],0,"Load shedding preserves core functionality by rejecting or deferring lower-priority work.","Define priorities before an overload event."],["Database bottleneck","API replicas scale from 5 to 50 but database connections saturate. What is the next investigation?",["Add more API replicas","Connection pooling, query efficiency and database capacity limits","Increase frontend animation duration","Disable transactions"],1,"Scaling the stateless tier can overload a shared database; connection pools and query load must be controlled.","Scale the whole request path, not only the visible tier."]]},{"title":"Distributed Systems & Consistency","sub":"DISTRIBUTED REASONING","outcome":"Reason about replication, coordination, consensus and partial failure.","intro":"Distributed systems operate across independent machines and networks. Messages can be delayed, duplicated or lost; nodes can disagree temporarily. Design around explicit guarantees rather than assumptions.","items":[["Network partition","Two data centers cannot communicate temporarily. What is the fundamental issue?",["A network partition between nodes","A CSS rendering error","A missing database index only","A browser cache miss"],0,"A partition prevents nodes from exchanging messages reliably; the system must choose how to preserve consistency and availability.","Assume network communication can fail independently of processes."],["Replica lag","A user writes a profile update and reads stale data from a replica. What happened?",["Replica lag","A dead-letter event","A cache stampede necessarily","A DNS hijack"],0,"An asynchronous replica has not applied the latest write yet.","Choose read routing or session guarantees for read-your-writes."],["Leader-follower","A replicated database has one leader accepting writes. What is a common follower role?",["Serve eligible reads and replicate the leader's log","Accept conflicting writes without coordination","Own all user interfaces","Replace backups"],0,"Followers replicate leader state and may serve reads depending on consistency requirements.","Understand the write authority and replica read guarantees."],["Quorum","A replicated key has 5 replicas. A read quorum is 3 and write quorum is 3. What is true about overlap?",["Any read and write quorum intersect in at least one replica","They can never overlap","The system has no replicas","All reads are globally linearizable automatically"],0,"With N=5, R=3 and W=3, R+W>N, so the sets intersect; full semantics still depend on protocol and version handling.","Use quorum arithmetic, then verify the actual consistency protocol."],["Consensus purpose","Why do distributed systems use consensus protocols such as Raft?",["To agree on an ordered replicated log despite failures within protocol assumptions","To compress images","To eliminate all network latency","To guarantee zero downtime"],0,"Consensus coordinates a consistent decision or log among nodes despite some failures, under timing and quorum assumptions.","Consensus improves agreement; it does not make failures disappear."],["Clock assumptions","Two servers timestamp events using their local clocks. Why can event ordering be wrong?",["Clocks can drift and timestamps may not reflect causality","UTC prevents all drift","Network packets arrive in perfect order","Databases never use clocks"],0,"Clock skew and delayed messages make wall-clock timestamps insufficient for causal ordering.","Do not treat wall-clock time as a perfect global sequence."],["Idempotent event processing","A consumer receives the same order-created event twice. What is the robust approach?",["Deduplicate by event identity or make the effect idempotent","Charge the customer twice","Delete all prior events","Assume queue delivery is exactly once"],0,"A durable deduplication record or idempotent state transition prevents duplicate side effects.","Design consumers for replay and duplicate delivery."],["Saga pattern","An order workflow spans inventory, payment and shipping services without a global transaction. What pattern coordinates steps and compensations?",["Saga","B-tree","CDN","Round robin"],0,"A saga sequences local transactions and defines compensating actions for failures.","Model long-running distributed workflows as state machines."],["Split brain","Two nodes both believe they are the leader and accept writes. What is this condition?",["Split brain","Cache warming","Cold start","Backpressure"],0,"Split brain creates conflicting authorities and can corrupt state without fencing or quorum controls.","Use quorum, leases or fencing tokens to prevent stale leaders writing."],["CAP trade-off","During a network partition, a distributed data store must choose between serving potentially stale data and rejecting some requests to preserve consistency. Which principle describes this?",["CAP theorem","Little's Law","ACID atomicity","MapReduce"],0,"CAP concerns consistency and availability trade-offs during a partition; it is not a simple always-pick-two slogan outside that condition.","Discuss CAP specifically under partition, with the system's actual guarantees."]]},{"title":"Reliability & Fault Tolerance","sub":"RESILIENCE ENGINEERING","outcome":"Contain failures, define service objectives and recover within business limits.","intro":"Production systems fail partially. Reliability engineering makes failure visible, bounded and recoverable through objectives, timeouts, isolation, redundancy and tested recovery plans.","items":[["SLI vs SLO","A service targets 99.9% successful requests over 30 days. What is 99.9%?",["An SLI observation","An SLO target","A database index","A deployment artifact"],1,"The target is the SLO; the measured success ratio is an SLI.","Separate measured indicators from reliability objectives."],["Error budget","A service has consumed its monthly error budget early. What should the team consider?",["Continue risky releases without review","Reduce release risk and prioritize reliability work","Delete the SLO","Disable incident response"],1,"An exhausted budget signals that reliability risk is too high relative to the agreed objective.","Use error budgets to balance delivery speed and reliability."],["Timeouts","A service calls a downstream API with no timeout. What is the main risk?",["Requests can hang and exhaust threads or connections","Latency becomes zero","The downstream becomes more reliable","Retries become idempotent"],0,"Unbounded waits consume finite resources and can cascade through the request path.","Set deadlines on every network dependency."],["Exponential backoff","A dependency is temporarily overloaded. Which retry pattern reduces synchronized retry storms?",["Immediate infinite retries","Exponential backoff with jitter and bounded attempts","Retry every 1 ms","Retry non-idempotent writes blindly"],1,"Backoff spreads retries over time; jitter prevents clients from retrying in lockstep.","Retries consume capacity—bound them and add jitter."],["Circuit breaker","A downstream dependency repeatedly fails. What does an open circuit breaker do?",["Stops calls temporarily and allows a later probe","Retries every call immediately","Deletes the dependency","Disables monitoring"],0,"The open state prevents repeated calls to an unhealthy dependency; half-open probes test recovery.","Use circuit breakers to stop cascading failures."],["Bulkheads","A slow recommendation dependency consumes every worker thread. Which pattern isolates resource pools?",["Bulkheads","Global shared thread pool","Infinite queue","Unbounded retries"],0,"Bulkheads allocate separate pools or limits so one dependency cannot exhaust all resources.","Isolate workloads and failure domains."],["Graceful degradation","A shopping app's recommendation service fails. What should checkout do?",["Fail checkout because recommendations are unavailable","Continue core checkout without recommendations","Retry recommendations synchronously forever","Delete the cart"],1,"Optional features should not block critical user journeys when their dependency fails.","Define critical and optional paths before incidents."],["Redundancy","A service must survive one availability-zone failure. What architecture helps?",["Deploy redundant instances across independent zones","Run one large instance in one zone","Store the only backup on the same disk","Disable health checks"],0,"Independent failure domains reduce the chance that one zone outage removes all capacity.","Place redundancy across genuinely independent failure domains."],["RPO and RTO","A service can lose at most 10 minutes of data and must recover within 1 hour. Which pair is correct?",["RPO 1 hour, RTO 10 minutes","RPO 10 minutes, RTO 1 hour","Both 10 minutes","Both 1 hour"],1,"RPO is tolerated data loss; RTO is time to restore service.","Translate business impact into explicit RPO and RTO."],["Restore testing","A team takes daily backups but has never restored one. What is the biggest gap?",["Backup file naming","Recoverability is unproven until restore is tested","The backups are automatically immutable","No gap exists"],1,"A backup that cannot be restored is not a reliable recovery mechanism.","Test restores and measure actual recovery time."]]},{"title":"Security, Privacy & Governance","sub":"SECURE BY DESIGN","outcome":"Threat-model systems and enforce identity, authorization, privacy and supply-chain controls.","intro":"Security is an architectural property. Identify assets and trust boundaries, minimize privileges, protect data, validate inputs and plan for compromise rather than assuming prevention is perfect.","items":[["Threat modeling","A team is designing file sharing. What should threat modeling identify first?",["Assets, actors, trust boundaries and abuse cases","Only the color palette","Only expected traffic","Only the programming language"],0,"Threat modeling starts with what must be protected, who may attack it and where trust changes.","Model assets and attack paths before selecting controls."],["Least privilege","A worker only needs read access to one object-storage bucket. What permission is appropriate?",["Cloud administrator","Dedicated workload identity with scoped read access","Shared root credentials","Public write access"],1,"Narrow permissions limit blast radius if the worker is compromised.","Grant the minimum permissions needed for each workload."],["Secrets management","A database password is committed to a public repository. What is the right response?",["Delete the visible line only","Revoke/rotate the exposed secret, audit usage and move it to a secret manager","Rename the variable","Make the repository private and assume safe"],1,"Once exposed, a secret must be treated as compromised; history may retain it.","Rotate exposed credentials and prevent future secret leakage."],["Encryption in transit","A mobile app communicates with its API over public networks. Which control protects data in transit?",["TLS with certificate validation","Base64 encoding","A hidden URL","A CSS class"],0,"TLS provides authenticated encrypted transport when correctly configured and validated.","Encrypt network traffic and validate peer identity."],["Encryption at rest","Sensitive customer records are stored on persistent disks. Which control addresses storage exposure?",["Encryption at rest with managed key controls","Only minifying JavaScript","Disabling logs","A longer URL"],0,"Encryption at rest reduces exposure from lost media or unauthorized storage access; key management remains critical.","Protect stored data and govern encryption keys."],["Authorization model","A user is authenticated but lacks permission to view another tenant's invoice. What must the API do?",["Allow because login succeeded","Check tenant-scoped authorization on every request","Trust the invoice ID to be secret","Check only in the frontend"],1,"Valid identity does not imply access to every resource. Tenant boundaries must be enforced server-side.","Authorize each resource action using trusted identity and policy."],["Input injection","A search endpoint concatenates user input directly into SQL. What is the primary mitigation?",["Parameterized queries and safe query construction","Hide the search box","Increase server RAM","Use client-side escaping only"],0,"Parameterized queries separate data from SQL syntax and prevent injection through values.","Treat input as data, never executable query syntax."],["Data minimization","An analytics service stores full payment card details despite needing only transaction totals. What should change?",["Collect and retain only data necessary for the purpose","Keep all data forever","Copy data into more services","Disable deletion"],0,"Data minimization reduces breach impact, compliance burden and retention risk.","Collect the least sensitive data needed and define retention."],["Auditability","An administrator changes a user's role. What record is important?",["An immutable or tamper-evident audit event with actor, action, target and time","A UI toast only","A screenshot on the admin laptop","No record if successful"],0,"Audit trails support investigation and accountability when privileged actions occur.","Log security-relevant actions with trustworthy context."],["Supply-chain security","A build downloads dependencies from public registries. What reduces dependency compromise risk?",["Lockfiles, trusted sources, provenance and vulnerability review","Install latest versions without review","Disable CI checks","Commit private tokens"],0,"Reproducible dependency resolution and provenance checks reduce supply-chain risk.","Secure build inputs as part of the system's threat model."]]},{"title":"Observability, Deployment & Operations","sub":"OPERATING SYSTEMS","outcome":"Operate services with telemetry, safe releases, incident response and cost controls.","intro":"A design is incomplete if operators cannot understand or safely change it. Observability connects symptoms to causes; deployment and incident practices reduce the risk of change.","items":[["Metrics","Which telemetry is best for tracking request rate, error ratio and latency over time?",["Metrics","Screenshots","Source code comments","DNS TXT records"],0,"Metrics aggregate numeric measurements and support dashboards and alerting.","Track rate, errors, duration and saturation."],["Structured logs","A production error needs filtering by request ID and tenant. What logging style helps?",["Structured logs with consistent fields","Unstructured paragraphs only","Console output without timestamps","No logs for privacy"],0,"Structured fields make logs queryable; sensitive data must still be redacted.","Log context consistently without leaking secrets or personal data."],["Distributed tracing","A request passes through gateway, order service and payment service. What reveals time spent in each hop?",["Distributed trace with correlated spans","A single CPU metric","A database schema diagram","A static screenshot"],0,"Traces correlate spans across services and expose where latency accumulates.","Propagate trace context across service boundaries."],["Golden signals","Which set is commonly used to understand service health?",["Latency, traffic, errors and saturation","Color, font, spacing and shadows","Users, logos, commits and branches","CPU only"],0,"The four golden signals summarize user-visible performance and resource pressure.","Instrument the service around user-impacting signals."],["Alert quality","An alert fires whenever CPU exceeds 50%, even with no user impact. What is the improvement?",["Alert on symptoms tied to SLOs and actionable conditions","Add more noisy alerts","Disable all alerting","Page everyone for every log line"],0,"Actionable alerts should indicate user impact or imminent risk and have a clear response.","Alert on meaningful symptoms, not arbitrary activity."],["Canary release","A new version is deployed to 5% of traffic first. What is this strategy?",["Canary deployment","Big-bang migration","Database sharding","Blue-green DNS poisoning"],0,"A canary exposes a small traffic slice to the new version and compares health before wider rollout.","Use limited exposure and automated rollback criteria."],["Blue-green deployment","Two production environments are kept ready and traffic switches from one to the other. What is this?",["Blue-green deployment","Vertical scaling","Cache aside","Leader election"],0,"Blue-green enables a controlled traffic switch and fast rollback, assuming data compatibility.","Plan application and schema compatibility across both environments."],["Rollback safety","A release includes an irreversible database schema change. What should be done before rollout?",["Use an expand-and-contract migration and define a recovery path","Deploy and hope","Delete backups","Disable health checks"],0,"Backward-compatible schema evolution allows old and new code to coexist during deployment and rollback.","Make database changes compatible across release versions."],["Incident command","A major outage is ongoing. What improves coordination?",["Clear incident commander, communication channel and roles","Everyone independently changes production","No status updates","Wait for a single engineer to diagnose everything"],0,"Defined roles reduce duplicated work and keep technical response and communication coordinated.","Establish incident roles and a shared timeline."],["Cost observability","A service's cloud bill doubles after launch. What should be examined first?",["Cost by service, workload, unit economics and recent changes","Only the homepage design","Delete all logs immediately","Increase instance size"],0,"Cost allocation and unit metrics identify which workloads or design changes drove spend.","Track cost per request, user, job or business transaction."]]},{"title":"Advanced Architecture & Global Systems","sub":"SYSTEM COMPOSITION","outcome":"Compose multi-region, event-driven and high-scale architectures with explicit trade-offs.","intro":"Advanced design combines all earlier disciplines. Global systems add geographic latency, data sovereignty, multi-region failure, streaming, workflow and organizational complexity.","items":[["Multi-region active-passive","A service needs disaster recovery but can tolerate failover downtime. Which design is simpler than active-active?",["Active-passive with tested failover","One server in one region","No replica or backup","Every region writes independently without conflict handling"],0,"Active-passive keeps a standby region ready and reduces concurrent-write conflict complexity.","Choose topology from RTO, RPO and operational capability."],["Active-active writes","Two regions accept writes to the same customer record. What must be designed?",["Conflict resolution and data ownership/consistency rules","Only a CDN","A larger font","No replication"],0,"Concurrent writes require a conflict strategy, ownership model or coordination mechanism.","Do not enable multi-writer without a conflict model."],["Global latency","Users are distributed worldwide and read mostly public content. What improves read latency?",["Regional edge caching and geographically distributed delivery","Route every read to one distant origin","Disable caching","Store content in browser cookies only"],0,"Edge delivery reduces round-trip time for cacheable content near users.","Place read-heavy, cacheable data close to consumers."],["Data residency","A region's law requires certain personal data to remain in-country. What is needed?",["Regional data placement, processing controls and backup policy","Only a regional CDN hostname","A user-facing disclaimer only","Ignore replicas"],0,"Residency applies to storage, processing, access and sometimes backups—not just the primary database.","Map data flows and replicas against residency constraints."],["Stream processing","A pipeline must aggregate click events continuously with low delay. What fits?",["A stream-processing architecture","A nightly manual spreadsheet","A static HTML page","A synchronous user request for every event"],0,"Stream processing handles continuous event flows with windows, state and delivery semantics.","Define event time, processing time, late data and replay behavior."],["CQRS","A workload has complex writes but many read views optimized differently. Which pattern separates command and query models?",["CQRS","DNS round robin","Circuit breaker","Vertical scaling"],0,"CQRS separates write-side domain operations from read-optimized projections; it adds synchronization complexity.","Use CQRS only when distinct read/write needs justify it."],["Workflow orchestration","A loan approval spans identity verification, credit check and notification with human review. What helps manage long-running state?",["A durable workflow orchestrator/state machine","A single long HTTP request","A browser timer","A cache key"],0,"A durable workflow persists progress, retries, timeouts and human tasks across failures.","Represent long-running business processes as durable state machines."],["Multi-tenant isolation","A SaaS platform hosts regulated enterprise tenants. What is a key architectural decision?",["Tenant isolation boundaries across data, compute, keys and authorization","Only tenant logo customization","One shared admin password","Trust tenant IDs from the browser"],0,"Isolation may require row-level controls, separate schemas, databases, keys or dedicated infrastructure based on risk.","Define and test tenant isolation at every layer."],["Architecture decision record","A team chooses a relational database over a document store. What should an ADR capture?",["Context, decision, alternatives, consequences and status","Only the chosen product logo","A list of all source files","The engineer's preference only"],0,"ADRs preserve reasoning and trade-offs so future teams can revisit decisions with context.","Record why a decision was made, not just what was selected."],["End-to-end design review","You are reviewing a global video platform. Which review is most complete?",["Only estimate CDN bandwidth","Trace upload, transcode, metadata, playback, authorization, failure recovery, observability and cost","Only choose a frontend framework","Only draw service boxes"],1,"A system review must cover user journeys, data flow, capacity, security, failure modes, operations and economics.","Evaluate complete request and data lifecycles, not isolated components."]]}];
const curriculum:Level[] = rawLevels.map((level:any, levelIndex:number)=>({
  id:`level-${levelIndex+1}`,title:level.title,subtitle:`LEVEL ${String(levelIndex+1).padStart(2,"0")} · ${level.sub}`,
  outcome:level.outcome,intro:level.intro,
  puzzles:level.items.map((item:any,index:number)=>({
    id:`l${levelIndex+1}-p${index+1}`,title:item[0],prompt:item[1],
    options:item[2],answer:item[3],explanation:item[4],takeaway:item[5],
    lesson:item[5]+" "+item[4]
  }))
}));

const STORAGE_KEY="anchon.academy.learned.v4";
const LAB_STORAGE_KEY="anchon.academy.lab.v2";
const references=[
 {name:"Google SRE Book",url:"https://sre.google/sre-book/table-of-contents/"},
 {name:"Google SRE Workbook",url:"https://sre.google/workbook/table-of-contents/"},
 {name:"AWS Well-Architected",url:"https://docs.aws.amazon.com/wellarchitected/latest/framework/"},
 {name:"AWS Builders' Library",url:"https://aws.amazon.com/builders-library/"},
 {name:"Azure Well-Architected",url:"https://learn.microsoft.com/en-us/azure/well-architected/"},
 {name:"Google Cloud Architecture Framework",url:"https://cloud.google.com/architecture/framework"},
 {name:"Designing Data-Intensive Applications resources",url:"https://dataintensive.net/"},
 {name:"Netflix Tech Blog",url:"https://netflixtechblog.com/"},
 {name:"Uber Engineering",url:"https://www.uber.com/blog/engineering/"},
 {name:"Meta Engineering",url:"https://engineering.fb.com/"}
];
const projectBriefs=[
 {name:"Campus marketplace",context:"Build a campus marketplace for 20,000 students. Students list products, search listings, message sellers and report abuse.",constraints:["Peak traffic is 8× the daily average during evening hours.","Private messages must only be visible to participants.","Images must remain available if an application instance is replaced."],deliverable:"A requirements map, capacity estimate, service boundary and first request/data-flow diagram."},
 {name:"Multi-tenant SaaS issue tracker",context:"Design an issue tracker used by 500 organizations. Teams create projects, assign issues, comment, search and receive notifications.",constraints:["A tenant must never read another tenant's records.","Search results may be eventually consistent for a few seconds.","A single noisy tenant must not exhaust shared capacity."],deliverable:"An API boundary, tenant-aware data model, authorization flow and isolation strategy."},
 {name:"Digital wallet and ledger",context:"Build a wallet for peer-to-peer transfers, balance history, refunds and reconciliation.",constraints:["A transfer must never debit without a corresponding credit.","Retries must not create duplicate transfers.","The ledger must be auditable and recoverable."],deliverable:"A transactional data model, invariants, idempotent APIs and concurrency-control design."},
 {name:"Short-video processing platform",context:"Users upload short videos, apply processing, publish clips and stream them to followers.",constraints:["Uploads can be large and processing can take minutes.","Workers can crash and messages can be delivered more than once.","Playback should not depend on the processing service being online."],deliverable:"An upload, queue, worker, object-storage and playback architecture."},
 {name:"Flash-sale commerce platform",context:"A commerce platform launches a limited-stock sale with sudden traffic spikes and concurrent checkout attempts.",constraints:["Inventory must not become negative.","The platform must protect payment and order services from overload.","Users need clear outcomes when checkout is delayed."],deliverable:"A traffic-management plan, inventory consistency model, cache strategy and asynchronous order flow."},
 {name:"Food delivery dispatch",context:"Customers place orders, restaurants prepare them and couriers accept and complete deliveries.",constraints:["Order state transitions must be valid.","Location updates arrive continuously and may be delayed.","Dispatch must continue when a downstream notification provider is unavailable."],deliverable:"A domain service map, event flow, queue partitioning and failure-handling strategy."},
 {name:"Online examination platform",context:"Run timed examinations for 100,000 candidates, autosave answers and submit responses reliably.",constraints:["A candidate must not lose saved answers after a browser refresh.","Exam submission has a strict deadline.","Traffic peaks at synchronized start and end times."],deliverable:"A resilient write path, autosave contract, admission-control strategy and observability plan."},
 {name:"Healthcare appointment platform",context:"Patients find clinicians, book appointments, receive reminders and view their own records.",constraints:["Patient data requires strict access control and auditability.","A reminder provider can be unavailable.","Double booking must be prevented."],deliverable:"A privacy boundary, transactional booking model, durable workflow and audit design."},
 {name:"Global collaboration workspace",context:"Teams collaborate on documents, comments and real-time activity across regions.",constraints:["Concurrent edits need a conflict strategy.","Users expect low latency across regions.","A regional outage must have a documented recovery plan."],deliverable:"A collaboration data flow, consistency model, regional topology and recovery plan."},
 {name:"Global video-on-demand platform",context:"Design a production-scale video platform with upload, transcoding, metadata, search, recommendations and global playback.",constraints:["Media processing is asynchronous and retryable.","Playback is globally distributed and cache-heavy.","The system must tolerate regional failures and control cost per viewing hour."],deliverable:"An end-to-end architecture, capacity model, failure analysis, security controls and operational plan."}
];
export function AcademyPage(){
 const [activeLevel,setActiveLevel]=useState(0);
 const [activeTopic,setActiveTopic]=useState(0);
 const [activeTab,setActiveTab]=useState<"learn"|"build">("learn");
 const [learned,setLearned]=useState<string[]>([]);
 const [completedLabs,setCompletedLabs]=useState<number[]>([]);
 useEffect(()=>{try{const topics=JSON.parse(localStorage.getItem(STORAGE_KEY)||"[]");if(Array.isArray(topics))setLearned(topics.filter((x:any)=>typeof x==="string"));const labs=JSON.parse(localStorage.getItem(LAB_STORAGE_KEY)||"[]");if(Array.isArray(labs))setCompletedLabs(labs.filter((x:any)=>Number.isInteger(x)&&x>=0&&x<10));}catch{/* local progress is optional */}},[]);
 const level=curriculum[activeLevel];
 const topic=level.puzzles[activeTopic];
 const topicKey=topic.id;
 const topicDone=learned.includes(topicKey);
 const totalTopics=curriculum.reduce((n,item)=>n+item.puzzles.length,0);
 const learnedCount=learned.length;
 const progress=Math.round(learnedCount/totalTopics*100);
 const saveLearned=(next:string[])=>{setLearned(next);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));}catch{/* keep session progress */}};
 const markLearned=()=>{if(!topicDone)saveLearned([...learned,topicKey]);};
 const chooseLevel=(index:number)=>{setActiveLevel(index);setActiveTopic(0);setActiveTab("learn");};
 const chooseTopic=(index:number)=>{setActiveTopic(index);setActiveTab("learn");};
 const completeLab=()=>{if(completedLabs.includes(activeLevel))return;const next=[...completedLabs,activeLevel];setCompletedLabs(next);try{localStorage.setItem(LAB_STORAGE_KEY,JSON.stringify(next));}catch{/* keep session progress */}};
 const resetProgress=()=>{saveLearned([]);setCompletedLabs([]);try{localStorage.removeItem(LAB_STORAGE_KEY);}catch{/* ignore */}};
 const project=projectBriefs[activeLevel];
 const implementationSteps=[
  "Translate the scenario into functional requirements and measurable quality attributes.",
  "Identify the trust boundaries, data owners and external dependencies.",
  "Place the components needed to satisfy the brief on the canvas.",
  "Connect request, data and asynchronous flows in the correct direction.",
  "Run the request or failure scenario, inspect the result and locate the broken boundary.",
  "Revise the graph and validate the architecture against every stated constraint."
 ];
 return <main className="academy-page academy-v3">
  <header className="academy-v3-hero">
   <div className="academy-v3-kicker">ANCHON ACADEMY / SYSTEM DESIGN STUDIO</div>
   <h1>Learn the system. <span>Build the architecture.</span></h1>
   <p>Ten open curriculum sections, one hundred engineering topics, and ten project-scale architecture studios. Learn by modelling real systems, connecting components, running requests and diagnosing failures.</p>
   <div className="academy-v3-progress"><div><span>LEARNING JOURNEY</span><strong>{learnedCount} / {totalTopics} topics studied</strong></div><strong>{progress}%</strong><div className="academy-v3-progress-track"><i style={{width:progress+"%"}}/></div></div>
   <div className="academy-v3-stats"><span><b>10</b> SECTIONS</span><span><b>100</b> ENGINEERING TOPICS</span><span><b>10</b> PROJECT STUDIOS</span><span><b>{completedLabs.length}</b> DESIGNS VALIDATED</span></div>
  </header>
  <div className="academy-v3-shell">
   <aside className="academy-v3-sidebar">
    <div className="academy-v3-sidebar-title"><span>CURRICULUM</span><small>ALL SECTIONS OPEN</small></div>
    {curriculum.map((item,index)=>{const done=item.puzzles.filter(p=>learned.includes(p.id)).length;return <button type="button" key={item.id} className={activeLevel===index?"active":""} onClick={()=>chooseLevel(index)}><span className="academy-v3-index">{String(index+1).padStart(2,"0")}</span><span className="academy-v3-section-name"><small>{item.subtitle.split("·").slice(1).join("·").trim()}</small><strong>{item.title}</strong><i>{done}/10 topics studied</i></span><ChevronRight size={15}/></button>;})}
    <button type="button" className="academy-v3-reset" onClick={resetProgress}><RotateCcw size={13}/> Reset learning progress</button>
   </aside>
   <section className="academy-v3-main">
    <div className="academy-v3-section-head"><div><span>{level.subtitle}</span><h2>{level.title}</h2><p>{level.outcome}</p></div><span className="academy-v3-open">OPEN CURRICULUM</span></div>
    <div className="academy-v3-intro">{level.intro}</div>
    <div className="academy-v3-tabs" role="tablist" aria-label="Section workspace">
     <button type="button" role="tab" aria-selected={activeTab==="learn"} className={activeTab==="learn"?"active":""} onClick={()=>setActiveTab("learn")}><BookOpen size={15}/> LEARN THE TOPICS <span>{level.puzzles.filter(p=>learned.includes(p.id)).length}/10</span></button>
     <button type="button" role="tab" aria-selected={activeTab==="build"} className={activeTab==="build"?"active":""} onClick={()=>setActiveTab("build")}><Waypoints size={15}/> SECTION DESIGN STUDIO <span>{completedLabs.includes(activeLevel)?"VALIDATED":"CANVAS"}</span></button>
    </div>
    {activeTab==="learn"?<div className="academy-v3-learning">
     <nav className="academy-v3-topic-list" aria-label="Topics in this section">{level.puzzles.map((item,index)=><button type="button" key={item.id} className={activeTopic===index?"active":""} onClick={()=>chooseTopic(index)}><span>{learned.includes(item.id)?<Check size={13}/>:String(index+1).padStart(2,"0")}</span><strong>{item.title}</strong><ChevronRight size={13}/></button>)}</nav>
     <article className="academy-v3-lesson">
      <div className="academy-v3-lesson-meta"><span>SECTION {String(activeLevel+1).padStart(2,"0")} / TOPIC {String(activeTopic+1).padStart(2,"0")}</span><span>{topicDone?"STUDIED":"LEARNING MODULE"}</span></div>
      <h3>{topic.title}</h3>
      <p className="academy-v3-lesson-lead">{topic.takeaway}</p>
      <section><h4>THE ENGINEERING CONCEPT</h4><p>{topic.explanation}</p><p>{topic.lesson}</p><h4>HOW IT WORKS IN A REAL SYSTEM</h4><p>Trace the lifecycle from the caller to the component that owns this responsibility. Identify the input contract, the state it reads or changes, the response returned to the caller, and the operational signal that proves the behavior is working.</p><h4>TRADE-OFFS AND FAILURE MODES</h4><p>{topic.takeaway} Consider overload, partial failure, retries, stale data, duplicate work and dependency outages where they apply. A production design must define what happens when the happy path is unavailable.</p></section>
      <section><h4>APPLY IT TO A REAL SYSTEM</h4><p>{topic.prompt.replace(/\?$/, ".")}</p><p>For the {project.name.toLowerCase()} project, decide how this concept changes the architecture. Identify the component that owns the behavior, the data it reads or writes, and what happens when the dependency is slow or unavailable.</p></section>
      <section className="academy-v3-practice"><h4>IMPLEMENTATION WORKFLOW</h4><ol>{implementationSteps.map(step=><li key={step}>{step}</li>)}</ol><p>Use the section design studio after studying the topics. Its component palette is scoped to the section's architecture problem; the canvas is where you prove the design, not a multiple-choice answer.</p></section>
      <div className="academy-v3-lesson-actions"><button type="button" className="academy-v3-mark" onClick={markLearned} disabled={topicDone}>{topicDone?<><Check size={14}/> TOPIC STUDIED</>:<>MARK TOPIC STUDIED <ArrowRight size={14}/></>}</button><button type="button" className="academy-v3-next" onClick={()=>{if(activeTopic<9)chooseTopic(activeTopic+1);else setActiveTab("build");}}>{activeTopic===9?"OPEN SECTION STUDIO":"NEXT TOPIC"} <ChevronRight size={14}/></button></div>
     </article>
    </div>:<div className="academy-v3-studio">
      <header><div><span>FINAL-YEAR PROJECT BRIEF / {String(activeLevel+1).padStart(2,"0")}</span><h3>{project.name}</h3><p>{project.context}</p></div><span className={completedLabs.includes(activeLevel)?"validated":""}>{completedLabs.includes(activeLevel)?"DESIGN VALIDATED":"ARCHITECTURE CHALLENGE"}</span></header>
      <div className="academy-v3-brief-grid"><section><h4>NON-NEGOTIABLE CONSTRAINTS</h4>{project.constraints.map(item=><p key={item}><Check size={13}/>{item}</p>)}</section><section><h4>YOUR DELIVERABLE</h4><p>{project.deliverable}</p><h4>DESIGN PROCESS</h4><ol>{implementationSteps.map(step=><li key={step}>{step}</li>)}</ol></section></div>
      <SystemDesignLab levelIndex={activeLevel} completed={completedLabs.includes(activeLevel)} onComplete={completeLab}/>
    </div>}
   </section>
  </div>
  <footer className="academy-v3-sources"><div><strong>ENGINEERING READING ROOM</strong><p>Curriculum concepts are aligned with established architecture and operations guidance. Read primary engineering material and compare the trade-offs against your own design.</p></div><div>{references.map(ref=><a href={ref.url} key={ref.name} target="_blank" rel="noreferrer">{ref.name}<ArrowRight size={12}/></a>)}</div></footer>
 </main>;
}
